-- migrations/0002_reviews_and_cron.sql
-- ============================================================================

-- justhairs — M1.5: appointment completion, review guard, rating views

-- ─────────────────────────────────────────────────────────────────────────────
-- Auto-complete past appointments
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function complete_past_appointments()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  update appointments
    set status = 'completed'
    where status = 'confirmed' and ends_at < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke execute on function complete_past_appointments() from anon, authenticated;
grant execute on function complete_past_appointments() to service_role;

-- Hourly cron. pg_cron must be enabled (Supabase → Database → Extensions).
create extension if not exists pg_cron;

select cron.unschedule('complete-past-appointments')
  where exists (select 1 from cron.job where jobname = 'complete-past-appointments');

select cron.schedule(
  'complete-past-appointments',
  '0 * * * *',
  $$select public.complete_past_appointments()$$
);

-- ─────────────────────────────────────────────────────────────────────────────
-- Reviews: only after a completed, owned appointment
-- ─────────────────────────────────────────────────────────────────────────────
drop policy if exists "reviews: own write" on reviews;

create policy "reviews: own insert" on reviews
  for insert to authenticated
  with check (
    customer_id = auth.uid()
    and exists (
      select 1 from appointments a
      where a.id = appointment_id
        and a.customer_id = auth.uid()
        and a.status = 'completed'
    )
  );

create policy "reviews: own update" on reviews
  for update to authenticated
  using (customer_id = auth.uid())
  with check (customer_id = auth.uid());

create policy "reviews: own delete" on reviews
  for delete to authenticated
  using (customer_id = auth.uid());

-- ─────────────────────────────────────────────────────────────────────────────
-- Rating aggregates
-- ─────────────────────────────────────────────────────────────────────────────
create or replace view service_ratings
with (security_invoker = true) as
  select service_id,
         round(avg(rating)::numeric, 1) as rating,
         count(*)::int as review_count
  from reviews
  where service_id is not null
  group by service_id;

create or replace view staff_ratings
with (security_invoker = true) as
  select staff_id,
         round(avg(rating)::numeric, 1) as rating,
         count(*)::int as review_count
  from reviews
  where staff_id is not null
  group by staff_id;

grant select on service_ratings, staff_ratings to anon, authenticated;

-- Public review feed — exposes only a first name + the service/staff name, so it
-- can run as owner (bypassing the profiles RLS) without leaking contact details.
create or replace view public_reviews
with (security_invoker = false) as
  select r.id,
         r.rating,
         r.comment,
         r.created_at,
         nullif(split_part(coalesce(p.full_name, ''), ' ', 1), '') as reviewer_first,
         s.name  as service_name,
         st.name as staff_name,
         r.service_id,
         r.staff_id
  from reviews r
  left join profiles p  on p.id  = r.customer_id
  left join services s  on s.id  = r.service_id
  left join staff    st on st.id = r.staff_id
  order by r.created_at desc;

grant select on public_reviews to anon, authenticated;

-- ============================================================================
-- migrations/0003_guest_booking_no_auth.sql
-- ============================================================================

-- justhairs — drop auth. Bookings are made by guests: contact details live on
-- the appointment row, and Stripe (or a "pay after the visit" choice) sets the
-- payment status. Nothing here touches existing seeded rows destructively.

-- ─────────────────────────────────────────────────────────────────────────────
-- appointments: guest-owned
-- ─────────────────────────────────────────────────────────────────────────────
alter table appointments
  alter column customer_id drop not null;

alter table appointments
  drop constraint if exists appointments_customer_id_fkey;

alter table appointments
  drop column if exists created_by;

alter table appointments
  add column if not exists customer_name  text,
  add column if not exists customer_email text,
  add column if not exists customer_phone text,
  add column if not exists confirmation_code text,
  add column if not exists payment_status text not null default 'unpaid'
    check (payment_status in ('unpaid', 'pay_later', 'paid')),
  add column if not exists stripe_session_id text;

create unique index if not exists appointments_confirmation_code_idx
  on appointments (confirmation_code);

-- Carry existing (auth-era) bookings' contact details onto the row itself,
-- while profiles is still around, so seeded reviews keep their reviewer names.
update appointments a
set customer_name  = coalesce(a.customer_name,  p.full_name),
    customer_email = coalesce(a.customer_email, p.email),
    customer_phone = coalesce(a.customer_phone, p.phone)
from profiles p
where p.id = a.customer_id;

update appointments set payment_status = 'pay_later' where payment_status = 'unpaid';

-- Short, unambiguous, human-readable reference (no 0/O/1/I).
create or replace function gen_confirmation_code()
returns text language plpgsql as $$
declare
  alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  code text := '';
  i int;
begin
  for i in 1..6 loop
    code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return code;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────────
-- Booking engine: no auth.uid(), callable by anon
-- ─────────────────────────────────────────────────────────────────────────────
-- KNOWN ISSUE (CODE_REVIEW.md #1): the "not exists overlapping appointment"
-- check + insert below has no exclusion constraint or row lock behind it.
-- Under READ COMMITTED, two concurrent calls for the same staff+slot can
-- both pass the check before either commits -> a real double-booking. A
-- GiST exclusion constraint on (staff_id, tstzrange(starts_at, ends_at)) or
-- a SELECT ... FOR UPDATE here would close this.
create or replace function book_appointment(
  p_service_id uuid,
  p_staff_id   uuid,
  p_starts_at  timestamptz
)
returns appointments
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_price    int;
  v_staff    uuid;
  v_ends     timestamptz;
  v_code     text;
  v_row      appointments;
begin
  select duration_min, price_cents into v_duration, v_price
  from services where id = p_service_id and active and online_booking;
  if v_duration is null then
    raise exception 'service not bookable' using errcode = 'P0001';
  end if;

  v_ends := p_starts_at + (v_duration || ' minutes')::interval;

  -- pick a concrete staff member from the still-available slots
  select s.staff_id into v_staff
  from get_available_slots(p_service_id, p_staff_id, (p_starts_at at time zone
    (select timezone from app_settings where id))::date) s
  where s.starts_at = p_starts_at
  limit 1;

  if v_staff is null then
    raise exception 'slot no longer available' using errcode = 'P0001';
  end if;

  -- retry a couple of times on the (astronomically unlikely) code collision
  for i in 1..5 loop
    begin
      v_code := gen_confirmation_code();
      insert into appointments
        (service_id, staff_id, starts_at, ends_at, status, price_cents, confirmation_code)
      values
        (p_service_id, v_staff, p_starts_at, v_ends, 'confirmed', v_price, v_code)
      returning * into v_row;
      return v_row;
    exception when unique_violation then
      -- try another code
    end;
  end loop;

  raise exception 'could not allocate a confirmation code' using errcode = 'P0001';
end;
$$;

-- Self-service reschedule/cancel required a signed-in owner — gone with auth.
drop function if exists reschedule_appointment(uuid, uuid, timestamptz);
drop function if exists cancel_appointment(uuid, text);

revoke execute on function book_appointment(uuid, uuid, timestamptz) from authenticated;
grant  execute on function book_appointment(uuid, uuid, timestamptz) to anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- RLS: appointments carry PII (name/email/phone) now, so no anon read at all.
-- The app reads them with the service-role key server-side; get_available_slots
-- still sees them because it's SECURITY DEFINER.
-- ─────────────────────────────────────────────────────────────────────────────
drop policy if exists "appointments: own read"   on appointments;
drop policy if exists "appointments: admin write" on appointments;

-- Reviews: submission is removed from the app (display only). Drop the
-- auth-scoped write policies; keep public read for the rating views/feed.
drop policy if exists "reviews: own write"  on reviews;
drop policy if exists "reviews: own insert" on reviews;
drop policy if exists "reviews: own update" on reviews;
drop policy if exists "reviews: own delete" on reviews;

-- Reviews no longer belong to a signed-in profile — the reviewer's name comes
-- from the appointment's contact details.
alter table reviews alter column customer_id drop not null;
alter table reviews drop constraint if exists reviews_customer_id_fkey;

create or replace view public_reviews
with (security_invoker = false) as
  select r.id,
         r.rating,
         r.comment,
         r.created_at,
         nullif(split_part(coalesce(a.customer_name, ''), ' ', 1), '') as reviewer_first,
         s.name  as service_name,
         st.name as staff_name,
         r.service_id,
         r.staff_id
  from reviews r
  left join appointments a on a.id = r.appointment_id
  left join services s     on s.id = r.service_id
  left join staff    st    on st.id = r.staff_id
  order by r.created_at desc;

grant select on public_reviews to anon;

-- ============================================================================
-- migrations/0004_day_availability.sql
-- ============================================================================

-- One round trip for a whole date range. The booking UI needs availability for
-- ~2 weeks at once (to disable full days and show "next available" chips); doing
-- that as N separate calls made the date/time steps feel slow.

create or replace function get_day_availability(
  p_service_id uuid,
  p_staff_id   uuid,
  p_from       date,
  p_days       int
)
returns table (starts_at timestamptz, staff_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  v_day date;
begin
  for i in 0..greatest(coalesce(p_days, 1) - 1, 0) loop
    v_day := p_from + i;
    return query
      select s.starts_at, s.staff_id
      from get_available_slots(p_service_id, p_staff_id, v_day) s;
  end loop;
end;
$$;

grant execute on function get_day_availability(uuid, uuid, date, int) to anon;

-- ============================================================================
-- migrations/0005_public_reviews_invoker.sql
-- ============================================================================

-- justhairs — public_reviews no longer needs SECURITY DEFINER.
--
-- The view ran as its owner only so it could read appointments.customer_name
-- (appointments has no anon read, it carries PII). Store the reviewer's first
-- name on the review itself instead, so the view reads only publicly readable
-- tables (reviews, services, staff) under the caller's own RLS.

alter table reviews add column if not exists reviewer_first text;

update reviews r
   set reviewer_first = nullif(split_part(coalesce(a.customer_name, ''), ' ', 1), '')
  from appointments a
 where a.id = r.appointment_id
   and r.reviewer_first is null;

create or replace view public_reviews
with (security_invoker = true) as
  select r.id,
         r.rating,
         r.comment,
         r.created_at,
         r.reviewer_first,
         s.name  as service_name,
         st.name as staff_name,
         r.service_id,
         r.staff_id
  from reviews r
  left join services s  on s.id  = r.service_id
  left join staff    st on st.id = r.staff_id
  order by r.created_at desc;

grant select on public_reviews to anon;

-- ============================================================================
-- migrations/0006_booking_integrity.sql
-- ============================================================================

-- justhairs — booking integrity and abuse hardening.
--   1. Double-booking is now impossible at the database level (CODE_REVIEW #1).
--   2. Abandoned, unpaid holds are released automatically.
--   3. The anon availability RPCs are bounded.
--   4. "Slot taken" has its own SQLSTATE so the app no longer string-matches.
--
-- NOTE: step 1 fails if existing rows already overlap for the same staff
-- member. Check first with:
--   select a.id, b.id from appointments a join appointments b
--     on a.staff_id = b.staff_id and a.id < b.id
--    and a.status in ('pending','confirmed','completed')
--    and b.status in ('pending','confirmed','completed')
--    and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(b.starts_at, b.ends_at, '[)');

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. No overlapping active appointments per staff member
-- ─────────────────────────────────────────────────────────────────────────────
create extension if not exists btree_gist with schema extensions;

alter table appointments
  drop constraint if exists appointments_no_overlap;

alter table appointments
  add constraint appointments_no_overlap
  exclude using gist (
    staff_id with =,
    tstzrange(starts_at, ends_at, '[)') with &&
  )
  where (staff_id is not null and status in ('pending', 'confirmed', 'completed'));

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. book_appointment: custom SQLSTATE JH409 for "slot no longer available",
--    bounded start time, and the exclusion violation mapped to the same error
--    (two concurrent callers: one wins, the other gets JH409).
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function book_appointment(
  p_service_id uuid,
  p_staff_id   uuid,
  p_starts_at  timestamptz
)
returns appointments
language plpgsql security definer set search_path = public as $$
declare
  v_duration int;
  v_price    int;
  v_staff    uuid;
  v_ends     timestamptz;
  v_code     text;
  v_row      appointments;
begin
  if p_starts_at is null
     or p_starts_at <= now()
     or p_starts_at > now() + interval '90 days' then
    raise exception 'slot no longer available' using errcode = 'JH409';
  end if;

  select duration_min, price_cents into v_duration, v_price
  from services where id = p_service_id and active and online_booking;
  if v_duration is null then
    raise exception 'service not bookable' using errcode = 'P0001';
  end if;

  v_ends := p_starts_at + (v_duration || ' minutes')::interval;

  select s.staff_id into v_staff
  from get_available_slots(p_service_id, p_staff_id, (p_starts_at at time zone
    (select timezone from app_settings where id))::date) s
  where s.starts_at = p_starts_at
  limit 1;

  if v_staff is null then
    raise exception 'slot no longer available' using errcode = 'JH409';
  end if;

  for i in 1..5 loop
    begin
      v_code := gen_confirmation_code();
      insert into appointments
        (service_id, staff_id, starts_at, ends_at, status, price_cents, confirmation_code)
      values
        (p_service_id, v_staff, p_starts_at, v_ends, 'confirmed', v_price, v_code)
      returning * into v_row;
      return v_row;
    exception
      when unique_violation then
        -- confirmation-code collision: try another code
        null;
      when exclusion_violation then
        raise exception 'slot no longer available' using errcode = 'JH409';
    end;
  end loop;

  raise exception 'could not allocate a confirmation code' using errcode = 'P0001';
end;
$$;

revoke execute on function book_appointment(uuid, uuid, timestamptz) from public;
grant  execute on function book_appointment(uuid, uuid, timestamptz) to anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. Bounded availability range for anon callers
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function get_day_availability(
  p_service_id uuid,
  p_staff_id   uuid,
  p_from       date,
  p_days       int
)
returns table (starts_at timestamptz, staff_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  v_day  date;
  v_days int := least(greatest(coalesce(p_days, 1), 1), 31);
begin
  -- Nothing to offer outside the bookable window; also keeps the work bounded.
  if p_from is null
     or p_from < current_date - 1
     or p_from > current_date + 90 then
    return;
  end if;

  for i in 0..v_days - 1 loop
    v_day := p_from + i;
    return query
      select s.starts_at, s.staff_id
      from get_available_slots(p_service_id, p_staff_id, v_day) s;
  end loop;
end;
$$;

revoke execute on function get_day_availability(uuid, uuid, date, int) from public;
grant  execute on function get_day_availability(uuid, uuid, date, int) to anon;

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Release abandoned holds
-- ─────────────────────────────────────────────────────────────────────────────
-- A hold is an appointment the guest started but never settled: still
-- 'unpaid' (not pay_later, not paid) with no Stripe Checkout session open.
-- Rows with a Checkout session are left alone — the guest may still be paying.
create or replace function release_stale_holds()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  delete from appointments
   where payment_status = 'unpaid'
     and stripe_session_id is null
     and created_at < now() - interval '15 minutes';
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke execute on function release_stale_holds() from public, anon, authenticated;
grant  execute on function release_stale_holds() to service_role;

select cron.unschedule('release-stale-holds')
  where exists (select 1 from cron.job where jobname = 'release-stale-holds');

select cron.schedule(
  'release-stale-holds',
  '*/5 * * * *',
  $$select public.release_stale_holds()$$
);

-- ─────────────────────────────────────────────────────────────────────────────
-- Default EXECUTE goes to PUBLIC, so revoking from anon/authenticated alone
-- (as 0002 did) leaves the cron-only function callable. Close that.
-- ─────────────────────────────────────────────────────────────────────────────
revoke execute on function complete_past_appointments() from public;
grant  execute on function complete_past_appointments() to service_role;

-- ============================================================================
-- migrations/0007_harden_and_index.sql
-- ============================================================================

-- justhairs — harden the Data API surface and the booking functions, add the
-- missing indexes. Re-runnable. Booking behaviour is unchanged (the function
-- bodies are the 0006 logic with every name schema-qualified).
--
-- Deploy order: ship the app code first (it calls the booking functions with
-- the secret/service-role key, which works before AND after this migration),
-- then apply this file. Applying it first would make the old build's
-- anon-key calls fail with "permission denied".
--
-- What this fixes (Supabase advisor / docs references in brackets):
--   1. Booking functions were callable by anyone holding the public key,
--      straight at /rest/v1/rpc/..., bypassing the app's validation.   [0028]
--   2. Functions used `search_path = public` (or none).                  [0011]
--   3. `reviews` was publicly readable including appointment_id, which opens
--      /book/confirmation/<id> (guest name + email). Only the display columns
--      are readable now; `staff_time_off` (reasons) and `app_settings` are
--      closed to the API roles.
--   4. Every table granted full DML to anon/authenticated, relying on RLS
--      alone. Grants and RLS are separate layers: revoke what isn't needed.
--   5. Policies named no role and called auth functions per row.   [0003, 0024]
--   6. Foreign keys without an index, one unused index.                 [0001]
--   7. pgcrypto in `public`.                                             [0014]
--   8. Overall rating averaged every review row in Node: now one view.

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Functions: empty search_path, schema-qualified, server-only
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function public.gen_confirmation_code()
returns text
language plpgsql
set search_path = ''
as $$
declare
  alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  code text := '';
  i int;
begin
  for i in 1..6 loop
    code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return code;
end;
$$;

create or replace function public.get_available_slots(
  p_service_id uuid,
  p_staff_id   uuid,
  p_day        date
)
returns table (starts_at timestamptz, staff_id uuid)
language plpgsql stable security definer set search_path = '' as $$
declare
  v_tz       text;
  v_step     int;
  v_duration int;
begin
  select timezone, slot_step_min into v_tz, v_step from public.app_settings where id;
  select duration_min into v_duration from public.services
    where id = p_service_id and active and online_booking;
  if v_duration is null then
    return;
  end if;

  return query
  with candidates as (
    select s.id
    from public.staff s
    where s.active
      and (p_staff_id is null or s.id = p_staff_id)
      and exists (
        select 1 from public.staff_services ss
        where ss.staff_id = s.id and ss.service_id = p_service_id
      )
  ),
  raw_slots as (
    select
      c.id as staff_id,
      ((p_day::timestamp + wh.start_time) at time zone v_tz
        + (n * v_step || ' minutes')::interval) as slot_start
    from candidates c
    join public.staff_working_hours wh
      on wh.staff_id = c.id
     and wh.weekday = extract(dow from p_day)::int
    cross join lateral generate_series(
      0,
      floor((extract(epoch from (wh.end_time - wh.start_time)) / 60 - v_duration) / v_step)::int
    ) as n
  ),
  valid as (
    select rs.staff_id, rs.slot_start
    from raw_slots rs
    where rs.slot_start > now()
      and not exists (
        select 1 from public.staff_time_off t
        where t.staff_id = rs.staff_id
          and tstzrange(t.starts_at, t.ends_at, '[)')
              && tstzrange(rs.slot_start, rs.slot_start + (v_duration || ' minutes')::interval, '[)')
      )
      and not exists (
        select 1 from public.appointments a
        where a.staff_id = rs.staff_id
          and a.status in ('pending', 'confirmed', 'completed')
          and tstzrange(a.starts_at, a.ends_at, '[)')
              && tstzrange(rs.slot_start, rs.slot_start + (v_duration || ' minutes')::interval, '[)')
      )
  )
  select distinct on (v.slot_start) v.slot_start, v.staff_id
  from valid v
  order by v.slot_start, v.staff_id;
end;
$$;

create or replace function public.get_day_availability(
  p_service_id uuid,
  p_staff_id   uuid,
  p_from       date,
  p_days       int
)
returns table (starts_at timestamptz, staff_id uuid)
language plpgsql stable security definer set search_path = '' as $$
declare
  v_day  date;
  v_days int := least(greatest(coalesce(p_days, 1), 1), 31);
begin
  -- Nothing to offer outside the bookable window; also keeps the work bounded.
  if p_from is null
     or p_from < current_date - 1
     or p_from > current_date + 90 then
    return;
  end if;

  for i in 0..v_days - 1 loop
    v_day := p_from + i;
    return query
      select s.starts_at, s.staff_id
      from public.get_available_slots(p_service_id, p_staff_id, v_day) s;
  end loop;
end;
$$;

create or replace function public.book_appointment(
  p_service_id uuid,
  p_staff_id   uuid,
  p_starts_at  timestamptz
)
returns public.appointments
language plpgsql security definer set search_path = '' as $$
declare
  v_duration int;
  v_price    int;
  v_staff    uuid;
  v_ends     timestamptz;
  v_code     text;
  v_row      public.appointments;
begin
  if p_starts_at is null
     or p_starts_at <= now()
     or p_starts_at > now() + interval '90 days' then
    raise exception 'slot no longer available' using errcode = 'JH409';
  end if;

  select duration_min, price_cents into v_duration, v_price
  from public.services where id = p_service_id and active and online_booking;
  if v_duration is null then
    raise exception 'service not bookable' using errcode = 'P0001';
  end if;

  v_ends := p_starts_at + (v_duration || ' minutes')::interval;

  select s.staff_id into v_staff
  from public.get_available_slots(p_service_id, p_staff_id, (p_starts_at at time zone
    (select timezone from public.app_settings where id))::date) s
  where s.starts_at = p_starts_at
  limit 1;

  if v_staff is null then
    raise exception 'slot no longer available' using errcode = 'JH409';
  end if;

  for i in 1..5 loop
    begin
      v_code := public.gen_confirmation_code();
      insert into public.appointments
        (service_id, staff_id, starts_at, ends_at, status, price_cents, confirmation_code)
      values
        (p_service_id, v_staff, p_starts_at, v_ends, 'confirmed', v_price, v_code)
      returning * into v_row;
      return v_row;
    exception
      when unique_violation then
        -- confirmation-code collision: try another code
        null;
      when exclusion_violation then
        raise exception 'slot no longer available' using errcode = 'JH409';
    end;
  end loop;

  raise exception 'could not allocate a confirmation code' using errcode = 'P0001';
end;
$$;

create or replace function public.complete_past_appointments()
returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_count integer;
begin
  update public.appointments
    set status = 'completed'
    where status = 'confirmed' and ends_at < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace function public.release_stale_holds()
returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_count integer;
begin
  delete from public.appointments
   where payment_status = 'unpaid'
     and stripe_session_id is null
     and created_at < now() - interval '15 minutes';
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Who may run them. By default any role can; the booking functions are only
-- ever called by the Next.js server with the secret (service_role) key, so the
-- public key gets none of them. gen_confirmation_code is internal.
revoke all on function public.gen_confirmation_code()                          from public, anon, authenticated;
revoke all on function public.get_available_slots(uuid, uuid, date)           from public, anon, authenticated;
revoke all on function public.get_day_availability(uuid, uuid, date, int)      from public, anon, authenticated;
revoke all on function public.book_appointment(uuid, uuid, timestamptz)        from public, anon, authenticated;
revoke all on function public.complete_past_appointments()                     from public, anon, authenticated;
revoke all on function public.release_stale_holds()                            from public, anon, authenticated;

grant execute on function public.get_available_slots(uuid, uuid, date)         to service_role;
grant execute on function public.get_day_availability(uuid, uuid, date, int)   to service_role;
grant execute on function public.book_appointment(uuid, uuid, timestamptz)     to service_role;
grant execute on function public.complete_past_appointments()                  to service_role;
grant execute on function public.release_stale_holds()                         to service_role;

-- Future functions in public start private too, instead of PUBLIC-executable.
-- (The second statement is global to role postgres, as Supabase documents; it
-- only affects functions created from now on.)
alter default privileges for role postgres in schema public revoke execute on functions from anon, authenticated;
alter default privileges for role postgres revoke execute on functions from public;

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Ratings: one aggregate instead of every review row
-- ─────────────────────────────────────────────────────────────────────────────
create or replace view public.overall_rating
with (security_invoker = true) as
  select round(avg(rating)::numeric, 1) as rating,
         count(*)::int                  as review_count
  from public.reviews;

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. RLS policies: start clean, name the roles, no per-row auth calls
-- ─────────────────────────────────────────────────────────────────────────────
do $$
declare
  p record;
begin
  for p in select schemaname, tablename, policyname from pg_policies where schemaname = 'public' loop
    execute format('drop policy %I on %I.%I', p.policyname, p.schemaname, p.tablename);
  end loop;
end;
$$;

-- Public catalog: readable, never writable through the API.
create policy "catalog: read" on public.service_categories
  for select to anon, authenticated using (true);
create policy "catalog: read" on public.staff_services
  for select to anon, authenticated using (true);
create policy "catalog: read" on public.staff_working_hours
  for select to anon, authenticated using (true);
create policy "catalog: read active" on public.services
  for select to anon, authenticated using (active);
create policy "catalog: read active" on public.staff
  for select to anon, authenticated using (active);
create policy "reviews: read" on public.reviews
  for select to anon, authenticated using (true);

-- appointments, app_settings and staff_time_off keep RLS on with no policy for
-- the API roles: they are read and written only by the server (service_role
-- bypasses RLS) and by the SECURITY DEFINER functions.

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. Grants: close everything, then open exactly what the app reads
-- ─────────────────────────────────────────────────────────────────────────────
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on tables    from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated;

grant select on public.service_categories, public.services, public.staff,
                public.staff_services, public.staff_working_hours
  to anon, authenticated;

-- Column-level: the display columns only. appointment_id (which opens a
-- guest's confirmation page) is not readable through the API.
grant select (id, rating, comment, created_at, reviewer_first, staff_id, service_id)
  on public.reviews to anon, authenticated;

grant select on public.service_ratings, public.staff_ratings,
                public.public_reviews, public.overall_rating
  to anon, authenticated;

comment on table public.appointments is
  'Guest bookings. Holds PII (name, email, phone): no Data API access, server-only (secret key).';
comment on table public.staff_time_off is
  'Staff leave, with reasons. No Data API access; read by the slot functions only.';
comment on table public.app_settings is
  'Salon-wide settings (single row). No Data API access; read by the slot functions only.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 5. Indexes: every foreign key, plus the two sweepers
-- ─────────────────────────────────────────────────────────────────────────────
create index if not exists services_category_idx          on public.services (category_id);
create index if not exists staff_services_service_idx     on public.staff_services (service_id);
create index if not exists staff_working_hours_staff_idx  on public.staff_working_hours (staff_id, weekday);
create index if not exists staff_time_off_staff_idx       on public.staff_time_off (staff_id, starts_at);
create index if not exists appointments_service_idx       on public.appointments (service_id);
create index if not exists reviews_staff_idx              on public.reviews (staff_id);
create index if not exists reviews_service_idx            on public.reviews (service_id);

-- small partial indexes for the cron sweepers
create index if not exists appointments_stale_hold_idx
  on public.appointments (created_at)
  where payment_status = 'unpaid' and stripe_session_id is null;
create index if not exists appointments_to_complete_idx
  on public.appointments (ends_at)
  where status = 'confirmed';

-- one Checkout session belongs to at most one appointment
create unique index if not exists appointments_stripe_session_idx
  on public.appointments (stripe_session_id)
  where stripe_session_id is not null;

-- customer_id is null on every guest booking: this index is never used.
drop index if exists public.appointments_customer_idx;

-- ─────────────────────────────────────────────────────────────────────────────
-- 6. Extension hygiene
-- ─────────────────────────────────────────────────────────────────────────────
do $$
begin
  if exists (
    select 1 from pg_extension e join pg_namespace n on n.oid = e.extnamespace
    where e.extname = 'pgcrypto' and n.nspname = 'public'
  ) then
    alter extension pgcrypto set schema extensions;
  end if;
end;
$$;

-- ============================================================================
-- migrations/0008_drop_unused_auth_schema.sql
-- ============================================================================

-- justhairs — remove the auth-era schema. OPTIONAL and DESTRUCTIVE.
--
-- Sign-in was removed in 0003 and nothing in the app reads or writes any of
-- this (CODE_REVIEW.md #12). Dropping it removes the dead tables, the trigger
-- on auth.users, and the policies and grants that went with them.
--
-- IRREVERSIBLE: any rows in profiles / orders / order_items / payments /
-- favorites / notifications (e.g. your own test sign-ups from the auth era)
-- are deleted, as are the always-null customer_id columns. Skip this file if
-- you want to keep that data; 0007 already closed these tables to the API.
-- Re-runnable.

-- the "create a profile on sign-up" hook on Supabase's auth table
drop trigger if exists on_auth_user_created on auth.users;
drop function if exists public.handle_new_user();

